package android.net.nsd;import java.util.*;import java.util.concurrent.*;import android.net.*;public class NsdManager {public static final int PROTOCOL_DNS_SD=1;public final List<DiscoveryListener> listeners=new ArrayList<>();public NetworkRequest request;public int legacy,scoped,stops,cancelled;public boolean defer;public final List<ResolveListener> waiting=new ArrayList<>();public final List<NsdServiceInfo> requests=new ArrayList<>();public interface DiscoveryListener {void onDiscoveryStarted(String s);void onDiscoveryStopped(String s);void onStartDiscoveryFailed(String s,int c);void onStopDiscoveryFailed(String s,int c);void onServiceFound(NsdServiceInfo i);void onServiceLost(NsdServiceInfo i);}public interface ResolveListener {void onResolveFailed(NsdServiceInfo i,int c);void onServiceResolved(NsdServiceInfo i);}public void discoverServices(String t,int p,DiscoveryListener l){legacy++;listeners.add(l);}public void discoverServices(String t,int p,NetworkRequest r,Executor e,DiscoveryListener l){scoped++;request=r;listeners.add(l);}public void stopServiceResolution(ResolveListener l){cancelled++;}public void stopServiceDiscovery(DiscoveryListener l){stops++;}public void resolveService(NsdServiceInfo i,ResolveListener l){if(defer){requests.add(i);waiting.add(l);}else l.onServiceResolved(i);}}
